import numpy as np
from scipy.optimize import least_squares, root
N=150000
np.set_printoptions(precision=10,suppress=False)

def solve3(m,k,starts):
    l=N-m-k
    if l<=0: return []
    r=np.array([m,k,l])/N
    sols=[]
    def fun(z, ret=False):
        A=np.exp(z[0]); B=np.exp(z[1])
        C=(N-m*A-k*B)/l
        if C<=0 or not np.isfinite(C):
            return np.array([1e6,1e6]) if not ret else (np.array([1e6,1e6]),None)
        q=np.array([A,B,C])
        f=np.array([np.dot(r,np.log(q))+10, np.dot(r,q*np.log(q))-10])
        return f if not ret else (f,q)
    for z0 in starts:
        res=least_squares(fun,z0,xtol=1e-15,ftol=1e-15,gtol=1e-15,max_nfev=5000)
        f,q=fun(res.x,True)
        if np.linalg.norm(f)<1e-8 and q is not None and np.all(q>0):
            sols.append(q)
    return sols

# initial guesses include two-level solutions around A=e^10, B=e^-10, and broad
base_starts=[]
for la in [1,5,8,9,10,10.5,11,12]:
    for lb in [-20,-15,-12,-10,-8,-5,-2,0,2,5]:
        base_starts.append([la,lb])

for m in [5,6,7,8]:
    for k in [1,2,3,5,10,20,50,100,300,1000]:
        sols=solve3(m,k,base_starts)
        if sols:
            # unique by q
            seen=[]
            for q in sols:
                if not any(np.allclose(q,s,rtol=1e-6,atol=1e-12) for s in seen): seen.append(q)
            print('m,k',m,k,'num',len(seen))
            for q in seen[:3]:
                r=np.array([m,k,N-m-k])/N
                F=r@(q*np.log(q)); B=-r@np.log(q)
                print('  q',q,'F,B',F,B)
